-- r12c_rc_live.sql
-- Executable PostgreSQL/pgTAP fragment: builds actual_relation / actual_column
-- from pg_catalog and emits the 9 accepted comparison assertions (ID01-ID09)
-- against expected_relation / expected_column (defined in r12c_rc_expected.sql,
-- which must be loaded into the same session before this fragment runs).
-- Design-time SQL text only where noted; the SELECTs below perform live
-- pg_catalog reads when executed against a real database. Owner assignment
-- deferred. No BEGIN/plan/finish wrapper included here.

-- actual_relation: live snapshot of relation-level shape from pg_catalog,
-- normalized to match expected_relation's column shapes/types exactly.
create temp table actual_relation (
  schema text,
  relation text,
  relkind text,
  persistence text,
  replica_identity text,
  rls_enabled boolean,
  rls_forced boolean,
  comment text
) on commit drop;

insert into actual_relation
  (schema, relation, relkind, persistence, replica_identity, rls_enabled, rls_forced, comment)
select
  n.nspname::text as schema,
  c.relname::text as relation,
  (case c.relkind
     when 'r' then 'table'
     when 'p' then 'partitioned table'
     when 'v' then 'view'
     when 'm' then 'materialized view'
     when 'f' then 'foreign table'
     when 'S' then 'sequence'
     else c.relkind::text
   end)::text as relkind,
  (case c.relpersistence
     when 'p' then 'permanent'
     when 'u' then 'unlogged'
     when 't' then 'temporary'
     else c.relpersistence::text
   end)::text as persistence,
  c.relreplident::text as replica_identity,
  c.relrowsecurity as rls_enabled,
  c.relforcerowsecurity as rls_forced,
  obj_description(c.oid, 'pg_class')::text as comment
from pg_catalog.pg_class c
join pg_catalog.pg_namespace n on n.oid = c.relnamespace
where n.nspname = 'public'
  and c.relkind in ('r', 'p');

-- actual_column: live snapshot of column-level shape from pg_catalog,
-- normalized to match expected_column's column shapes/types exactly.
create temp table actual_column (
  schema text,
  relation text,
  column_name text,
  ordinal_position int,
  data_type text,
  formatted_type text,
  udt_schema text,
  udt_name text,
  nullable boolean,
  default_expression text,
  is_identity boolean,
  identity_generation text,
  generated_kind text,
  generated_expression text,
  collation_name text,
  comment text
) on commit drop;

insert into actual_column
  (schema, relation, column_name, ordinal_position, data_type, formatted_type,
   udt_schema, udt_name, nullable, default_expression, is_identity,
   identity_generation, generated_kind, generated_expression, collation_name, comment)
select
  n.nspname::text as schema,
  c.relname::text as relation,
  a.attname::text as column_name,
  a.attnum::int as ordinal_position,
  isc.data_type::text as data_type,
  format_type(a.atttypid, a.atttypmod)::text as formatted_type,
  tn.nspname::text as udt_schema,
  t.typname::text as udt_name,
  (not a.attnotnull) as nullable,
  pg_get_expr(ad.adbin, ad.adrelid)::text as default_expression,
  (a.attidentity <> '') as is_identity,
  (case a.attidentity
     when 'a' then 'ALWAYS'
     when 'd' then 'BY DEFAULT'
     else NULL
   end)::text as identity_generation,
  (case a.attgenerated
     when 's' then 's'
     else NULL
   end)::text as generated_kind,
  (case
     when a.attgenerated = 's' then pg_get_expr(ad.adbin, ad.adrelid)
     else NULL
   end)::text as generated_expression,
  (case
     when a.attcollation <> 0
       then con.nspname || '.' || co.collname
     else NULL
   end)::text as collation_name,
  col_description(c.oid, a.attnum)::text as comment
from pg_catalog.pg_attribute a
join pg_catalog.pg_class c on c.oid = a.attrelid
join pg_catalog.pg_namespace n on n.oid = c.relnamespace
join pg_catalog.pg_type t on t.oid = a.atttypid
join pg_catalog.pg_namespace tn on tn.oid = t.typnamespace
left join pg_catalog.pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum
left join pg_catalog.pg_collation co on co.oid = a.attcollation
left join pg_catalog.pg_namespace con on con.oid = co.collnamespace
join information_schema.columns isc
  on isc.table_schema = n.nspname
 and isc.table_name = c.relname
 and isc.column_name = a.attname
where n.nspname = 'public'
  and c.relkind in ('r', 'p')
  and a.attnum > 0
  and not a.attisdropped;

-- ID01: relation count — actual relation row count must equal expected relation row count
select is(
  (select count(*)::int from actual_relation),
  (select count(*)::int from expected_relation),
  'ID01_relation_count'
);

-- ID02: relation missing — expected relations absent from actual (full-row EXCEPT, expected -> actual)
select is_empty(
  $$
  select er.schema, er.relation, er.relkind, er.persistence, er.replica_identity,
         er.rls_enabled, er.rls_forced, er.comment
  from expected_relation er
  except
  select ar.schema, ar.relation, ar.relkind, ar.persistence, ar.replica_identity,
         ar.rls_enabled, ar.rls_forced, ar.comment
  from actual_relation ar
  $$,
  'ID02_relation_missing'
);

