-- ID09: column no-weaker — actual column must not be weaker than expected on the same key:
-- nullable must not have gone from FALSE (expected, not-null) to TRUE (actual, nullable),
-- and data_type/formatted_type must not have diverged from the expected type.
select diag(d.line) from (
  select format('NO_WEAKER schema=%s relation=%s column=%s expected_nullable=%s actual_nullable=%s expected_data_type=%s actual_data_type=%s expected_formatted_type=%s actual_formatted_type=%s expected_default=%s actual_default=%s',
                 x.schema, x.relation, x.column_name, x.expected_nullable, x.actual_nullable,
                 x.expected_data_type, x.actual_data_type, x.expected_formatted_type, x.actual_formatted_type,
                 x.expected_default_expression, x.actual_default_expression) as line
    from (
      select ec.schema, ec.relation, ec.column_name,
             ec.nullable as expected_nullable, ac.nullable as actual_nullable,
             ec.data_type as expected_data_type, ac.data_type as actual_data_type,
             ec.formatted_type as expected_formatted_type, ac.formatted_type as actual_formatted_type,
             ec.default_expression as expected_default_expression, ac.default_expression as actual_default_expression
      from expected_column ec
      join actual_column ac
        on ac.schema = ec.schema
       and ac.relation = ec.relation
       and ac.column_name = ec.column_name
      where (ec.nullable = FALSE and ac.nullable = TRUE)
         or (ec.data_type is distinct from ac.data_type)
         or (ec.formatted_type is distinct from ac.formatted_type)
         or (ec.default_expression is distinct from ac.default_expression)
    ) x
   limit 20
) d;
