  from expected_column ec
  join actual_column ac
    on ac.schema = ec.schema
   and ac.relation = ec.relation
   and ac.column_name = ec.column_name
  where (ec.nullable = FALSE and ac.nullable = TRUE)
     or (ec.data_type is distinct from ac.data_type)
     or (ec.formatted_type is distinct from ac.formatted_type)
     or (ec.default_expression is distinct from ac.default_expression)
  $$,
  'ID09_column_no_weaker: not-null, type and default expression remain exact'
