-- r12c_k_live.sql
-- Builds actual_* shapes for plan K (primary key, unique constraint, check
-- constraint, foreign key, explicit index) straight from pg_catalog, then
-- runs pgTAP assertions 10-34 (five per category) against the temp tables
-- created by /private/tmp/r12c_k_expected.sql (expected_primary_key,
-- expected_unique_constraint, expected_check_constraint, expected_foreign_key,
-- expected_explicit_index must already exist in this session).
--
-- Explicit index definition text is excluded per R5 (source-format
-- traceability only); key/include column order, predicate, method, valid and
-- ready are preserved instead. Explicit indexes are those NOT backing a
-- primary key or unique constraint.

-- ============================================================
-- actual_primary_key
-- ============================================================
create temp table actual_primary_key as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  con.conname::text as constraint_name,
  (
    select array_agg(a.attname::text order by k.ord)
    from unnest(con.conkey) with ordinality as k(attnum, ord)
    join pg_attribute a
      on a.attrelid = con.conrelid and a.attnum = k.attnum
  ) as columns,
  pg_get_constraintdef(con.oid, true) as definition,
  con.convalidated as validated,
  con.condeferrable as deferrable_flag,
  con.condeferred as initially_deferred
from pg_constraint con
join pg_class c on c.oid = con.conrelid
join pg_namespace n on n.oid = c.relnamespace
where con.contype = 'p'
  and n.nspname = 'public';

-- ============================================================
-- actual_unique_constraint
-- ============================================================
create temp table actual_unique_constraint as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  con.conname::text as constraint_name,
  (
    select array_agg(a.attname::text order by k.ord)
    from unnest(con.conkey) with ordinality as k(attnum, ord)
    join pg_attribute a
      on a.attrelid = con.conrelid and a.attnum = k.attnum
  ) as columns,
  pg_get_constraintdef(con.oid, true) as definition,
  coalesce(i.indnullsnotdistinct, false) as nulls_not_distinct,
  con.convalidated as validated,
  con.condeferrable as deferrable_flag,
  con.condeferred as initially_deferred
from pg_constraint con
join pg_class c on c.oid = con.conrelid
join pg_namespace n on n.oid = c.relnamespace
left join pg_index i on i.indexrelid = con.conindid
where con.contype = 'u'
  and n.nspname = 'public';

-- ============================================================
-- actual_check_constraint
-- normalized_expression strips the outer CHECK ( ... ) wrapper of
-- pg_get_constraintdef's output; this is the sole, deterministic
-- normalization rule applied.
-- ============================================================
create temp table actual_check_constraint as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  con.conname::text as constraint_name,
  pg_get_constraintdef(con.oid, true) as definition,
  regexp_replace(
    pg_get_constraintdef(con.oid, true),
    '^CHECK \((.*)\)$',
    '\1'
  ) as normalized_expression,
  con.convalidated as validated,
  (not con.convalidated) as not_valid,
  con.condeferrable as deferrable_flag,
  con.condeferred as initially_deferred,
  con.connoinherit as no_inherit
from pg_constraint con
join pg_class c on c.oid = con.conrelid
join pg_namespace n on n.oid = c.relnamespace
where con.contype = 'c'
  and n.nspname = 'public';

-- ============================================================
-- actual_foreign_key
-- ============================================================
create temp table actual_foreign_key as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  con.conname::text as constraint_name,
  (
    select array_agg(a.attname::text order by k.ord)
    from unnest(con.conkey) with ordinality as k(attnum, ord)
    join pg_attribute a
      on a.attrelid = con.conrelid and a.attnum = k.attnum
  ) as local_columns,
  rn.nspname::text as referenced_schema,
  rc.relname::text as referenced_relation,
  (
    select array_agg(a.attname::text order by k.ord)
    from unnest(con.confkey) with ordinality as k(attnum, ord)
    join pg_attribute a
      on a.attrelid = con.confrelid and a.attnum = k.attnum
  ) as referenced_columns,
  case con.confmatchtype
    when 'f' then 'MATCH FULL'
    when 'p' then 'MATCH PARTIAL'
    else 'MATCH SIMPLE'
  end as match_type,
  case con.confupdtype
    when 'a' then 'NO ACTION'
    when 'r' then 'RESTRICT'
    when 'c' then 'CASCADE'
    when 'n' then 'SET NULL'
    when 'd' then 'SET DEFAULT'
  end as on_update,
  case con.confdeltype
    when 'a' then 'NO ACTION'
    when 'r' then 'RESTRICT'
    when 'c' then 'CASCADE'
    when 'n' then 'SET NULL'
    when 'd' then 'SET DEFAULT'
  end as on_delete,
  pg_get_constraintdef(con.oid, true) as definition,
  con.convalidated as validated,
  con.condeferrable as deferrable_flag,
  con.condeferred as initially_deferred
from pg_constraint con
join pg_class c on c.oid = con.conrelid
join pg_namespace n on n.oid = c.relnamespace
join pg_class rc on rc.oid = con.confrelid
join pg_namespace rn on rn.oid = rc.relnamespace
where con.contype = 'f'
  and n.nspname = 'public';

-- ============================================================
-- actual_explicit_index
-- Explicit = not the supporting index of a primary key or unique
-- constraint. Definition text is intentionally excluded per R5.
-- ============================================================
create temp table actual_explicit_index as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  ic.relname::text as index_name,
  i.indisunique as "unique",
  am.amname::text as method,
  (
    select array_agg(
             pg_get_indexdef(i.indexrelid, gs.pos, true) ||
             (case when (i.indoption[gs.pos - 1] & 1) = 1 then ' DESC' else '' end)
             order by gs.pos
           )
    from generate_series(1, i.indnkeyatts) as gs(pos)
  ) as key_expressions_or_columns_in_order,
  coalesce((
    select array_agg(
             pg_get_indexdef(i.indexrelid, gs.pos, true)
             order by gs.pos
           )
    from generate_series(i.indnkeyatts + 1, i.indnatts) as gs(pos)
  ), ARRAY[]::text[]) as include_columns_in_order,
  pg_get_expr(i.indpred, i.indrelid, true) as predicate,
  i.indisvalid as valid,
  i.indisready as ready
from pg_index i
join pg_class ic on ic.oid = i.indexrelid
join pg_class c on c.oid = i.indrelid
join pg_namespace n on n.oid = c.relnamespace
join pg_am am on am.oid = ic.relam
where n.nspname = 'public'
  and not exists (
    select 1
    from pg_constraint con2
    where con2.conindid = i.indexrelid
      and con2.contype in ('p', 'u')
  );

-- ============================================================
-- Assertions 10-14: actual_primary_key vs expected_primary_key
-- ============================================================

-- 10: row count matches
select is(
  (select count(*)::int from actual_primary_key),
  (select count(*)::int from expected_primary_key),
  'plan K 10: actual_primary_key row count matches expected_primary_key'
);

-- 11: no missing full rows (present in expected, absent from actual)
select is_empty(
  $$
    select schema, relation, constraint_name, columns, definition,
           validated, deferrable_flag, initially_deferred
    from expected_primary_key
    except
    select schema, relation, constraint_name, columns, definition,
           validated, deferrable_flag, initially_deferred
    from actual_primary_key
  $$,
  'plan K 11: no primary key rows missing from actual vs expected'
);

-- 12: no unexpected full rows (present in actual, absent from expected)
select is_empty(
  $$
    select schema, relation, constraint_name, columns, definition,
           validated, deferrable_flag, initially_deferred
    from actual_primary_key
    except
    select schema, relation, constraint_name, columns, definition,
           validated, deferrable_flag, initially_deferred
    from expected_primary_key
  $$,
  'plan K 12: no unexpected primary key rows in actual vs expected'
);

-- 13: no duplicate constraint identities in actual
select is_empty(
  $$
    select schema, relation, constraint_name
    from actual_primary_key
    group by schema, relation, constraint_name
    having count(*) > 1
  $$,
  'plan K 13: no duplicate actual_primary_key constraint identities'
);

-- 14: no-weaker (matched constraint must not have dropped validation)
select is_empty(
  $$
    select e.schema, e.relation, e.constraint_name
    from expected_primary_key e
    join actual_primary_key a
      on a.schema = e.schema
     and a.relation = e.relation
     and a.constraint_name = e.constraint_name
    where e.validated = true
      and a.validated = false
  $$,
  'plan K 14: no primary key weakened (validated -> not validated)'
);

-- ============================================================
-- Assertions 15-19: actual_unique_constraint vs expected_unique_constraint
-- ============================================================

-- 15: row count matches
select is(
  (select count(*)::int from actual_unique_constraint),
  (select count(*)::int from expected_unique_constraint),
  'plan K 15: actual_unique_constraint row count matches expected_unique_constraint'
);

-- 16: no missing full rows
select is_empty(
  $$
    select schema, relation, constraint_name, columns, definition,
           nulls_not_distinct, validated, deferrable_flag, initially_deferred
    from expected_unique_constraint
    except
    select schema, relation, constraint_name, columns, definition,
           nulls_not_distinct, validated, deferrable_flag, initially_deferred
    from actual_unique_constraint
  $$,
  'plan K 16: no unique constraint rows missing from actual vs expected'
);

-- 17: no unexpected full rows
select is_empty(
  $$
    select schema, relation, constraint_name, columns, definition,
           nulls_not_distinct, validated, deferrable_flag, initially_deferred
    from actual_unique_constraint
    except
    select schema, relation, constraint_name, columns, definition,
           nulls_not_distinct, validated, deferrable_flag, initially_deferred
    from expected_unique_constraint
  $$,
  'plan K 17: no unexpected unique constraint rows in actual vs expected'
);

-- 18: no duplicate constraint identities in actual
select is_empty(
  $$
    select schema, relation, constraint_name
    from actual_unique_constraint
    group by schema, relation, constraint_name
    having count(*) > 1
  $$,
  'plan K 18: no duplicate actual_unique_constraint constraint identities'
);

-- 19: no-weaker (validated dropped, or nulls_not_distinct downgraded)
select is_empty(
  $$
    select e.schema, e.relation, e.constraint_name
    from expected_unique_constraint e
    join actual_unique_constraint a
      on a.schema = e.schema
     and a.relation = e.relation
     and a.constraint_name = e.constraint_name
    where (e.validated = true and a.validated = false)
       or (e.nulls_not_distinct = true and a.nulls_not_distinct = false)
  $$,
  'plan K 19: no unique constraint weakened (validated or nulls_not_distinct)'
);

-- ============================================================
-- Assertions 20-24: actual_check_constraint vs expected_check_constraint
-- ============================================================

-- 20: row count matches
select diag(d.line) from (
  select format('COUNT_DELTA_IDENTITY %s schema=%s relation=%s constraint_name=%s', x.side, x.schema, x.relation, x.constraint_name) as line
    from (
      select 'expected_only' as side, schema, relation, constraint_name
        from expected_check_constraint
      except
      select 'expected_only', schema, relation, constraint_name
        from actual_check_constraint
      union all
      select 'actual_only' as side, schema, relation, constraint_name
        from actual_check_constraint
      except
      select 'actual_only', schema, relation, constraint_name
        from expected_check_constraint
    ) x
   limit 20
) d;
select is(
  (select count(*)::int from actual_check_constraint),
  (select count(*)::int from expected_check_constraint),
  'plan K 20: actual_check_constraint row count matches expected_check_constraint'
);

-- 21: no missing full rows
select is_empty(
  $$
    select schema, relation, constraint_name, definition, normalized_expression,
           validated, not_valid, deferrable_flag, initially_deferred, no_inherit
    from expected_check_constraint
    except
    select schema, relation, constraint_name, definition, normalized_expression,
           validated, not_valid, deferrable_flag, initially_deferred, no_inherit
    from actual_check_constraint
  $$,
  'plan K 21: no check constraint rows missing from actual vs expected'
);

-- 22: no unexpected full rows
select is_empty(
  $$
    select schema, relation, constraint_name, definition, normalized_expression,
           validated, not_valid, deferrable_flag, initially_deferred, no_inherit
    from actual_check_constraint
    except
    select schema, relation, constraint_name, definition, normalized_expression,
           validated, not_valid, deferrable_flag, initially_deferred, no_inherit
    from expected_check_constraint
  $$,
  'plan K 22: no unexpected check constraint rows in actual vs expected'
);

-- 23: no duplicate constraint identities in actual
select is_empty(
  $$
    select schema, relation, constraint_name
    from actual_check_constraint
    group by schema, relation, constraint_name
    having count(*) > 1
  $$,
  'plan K 23: no duplicate actual_check_constraint constraint identities'
);

-- 24: no-weaker (validated dropped, or NOT VALID introduced)
select is_empty(
  $$
    select e.schema, e.relation, e.constraint_name
    from expected_check_constraint e
    join actual_check_constraint a
