  ON "r12c_expected_storage"."objects"
  AS PERMISSIVE
  FOR SELECT
  TO "authenticated"
  USING (bucket_id = 'work-order-files' and (select auth.uid()) is not null and exists ( select 1 from public.dealer_members dm where dm.user_id = (select auth.uid()) and dm.status = 'active' and dm.dealer_id::text = (storage.foldername(objects.name))[1] ));

create temp table expected_policy_catalog (
  schema_name text NOT NULL,
  relation_name text NOT NULL,
  policy_name text NOT NULL,
  command text NOT NULL,
  permissive boolean NOT NULL,
  roles_in_order text[] NOT NULL,
  using_expression text,
  with_check_expression text
) on commit drop;
-- Deparse qual/with_check directly from pg_policy/pg_class/pg_namespace via
-- pg_get_expr under a fixed pg_catalog-only search_path, rather than through
-- the pg_policies view under whatever ambient search_path happens to be
-- active. pg_get_expr's qualification decisions for referenced tables are
-- search-path-dependent; forcing pg_catalog-only here (and identically at
-- the actual_policy_catalog capture site below) guarantees every non-
-- pg_catalog table reference is fully schema-qualified on BOTH sides, so the
-- only remaining textual difference is the shadow-schema prefix itself,
-- which is then deterministically mapped to its live-schema equivalent.
SET LOCAL search_path = pg_catalog;
INSERT INTO expected_policy_catalog (schema_name, relation_name, policy_name, command, permissive, roles_in_order, using_expression, with_check_expression)
  SELECT
    case n.nspname
      when 'r12c_expected_public' then 'public'
      when 'r12c_expected_storage' then 'storage'
    end,
    c.relname::text,
    pol.polname::text,
    (case pol.polcmd
       when 'r' then 'SELECT'
       when 'a' then 'INSERT'
       when 'w' then 'UPDATE'
       when 'd' then 'DELETE'
       when '*' then 'ALL'
     end)::text,
    pol.polpermissive,
    (case
       when pol.polroles = '{0}' then array['public']::text[]
       else (select array_agg(r.rolname::text order by r.rolname) from pg_authid r where r.oid = any(pol.polroles))
     end),
    regexp_replace(regexp_replace(pg_get_expr(pol.polqual, pol.polrelid), 'r12c_expected_public\.', 'public.', 'g'), 'r12c_expected_storage\.', 'storage.', 'g'),
    regexp_replace(regexp_replace(pg_get_expr(pol.polwithcheck, pol.polrelid), 'r12c_expected_public\.', 'public.', 'g'), 'r12c_expected_storage\.', 'storage.', 'g')
  FROM pg_policy pol
  JOIN pg_class c ON c.oid = pol.polrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname IN ('r12c_expected_public', 'r12c_expected_storage');

-- Capture expected deparsed expressions while the shadow schemas' catalog
-- entries exist, then restore the outer pgTAP search path.
SET LOCAL search_path = r12c_catalog_pgtap, pg_temp, public, extensions;

