-- 40-44: policy
-- actual_policy_catalog: materialized once from pg_policy/pg_class/pg_namespace
-- via pg_get_expr under the SAME fixed pg_catalog-only search_path used for
-- expected_policy_catalog's capture above, so qual/with_check qualification
-- decisions are made identically on both sides (see comment there). Restored
-- to the baseline search_path immediately after materialization.
SET LOCAL search_path = pg_catalog;
create temp table actual_policy_catalog as
select
  n.nspname::text as schemaname,
  c.relname::text as tablename,
  pol.polname::text as policyname,
  (case pol.polcmd
     when 'r' then 'SELECT'
     when 'a' then 'INSERT'
     when 'w' then 'UPDATE'
     when 'd' then 'DELETE'
     when '*' then 'ALL'
   end)::text as cmd,
  pol.polpermissive as permissive,
  (case
     when pol.polroles = '{0}' then array['public']::text[]
     else (select array_agg(r.rolname::text order by r.rolname) from pg_authid r where r.oid = any(pol.polroles))
   end) as roles,
  pg_get_expr(pol.polqual, pol.polrelid) as qual,
  pg_get_expr(pol.polwithcheck, pol.polrelid) as with_check
from pg_policy pol
join pg_class c on c.oid = pol.polrelid
join pg_namespace n on n.oid = c.relnamespace
where n.nspname in ('public', 'storage');
SET LOCAL search_path = r12c_catalog_pgtap, pg_temp, public, extensions;

select is(
  (select count(*)::bigint from actual_policy_catalog),
  190::bigint,
  '40 policy EXACT_COUNT: expected 190 canonical policies across public (173) and storage (17)'
);

