-- 55 diagnostics: report each offending row's raw ACL state so a human can
-- distinguish an expected-data defect (this file's 24/43 identity sets are
-- mis-scoped) from a genuine un-revoked PUBLIC EXECUTE grant on a "zero-
-- grant" function (a migration-side defect outside this file's authority).
-- proacl_is_null=true means the function relies on the PostgreSQL default
-- ACL (implicit PUBLIC EXECUTE never revoked); proacl otherwise shows the
-- explicit ACL array for direct inspection.
select diag(d.line) from (
  select format('GRANTABLE_ON_CANONICAL function=%s.%s(%s) grantee=%s', n.nspname, p.proname, oidvectortypes(p.proargtypes), r.rolname) as line
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
    join pg_authid r on r.oid = a.grantee
   where n.nspname = 'public' and p.prokind = 'f'
     and r.rolname in ('authenticated', 'service_role')
     and a.is_grantable
   limit 20
) d;
select diag(d.line) from (
  select format('ZERO_GRANT_STILL_EXECUTABLE schema=%s function=%s(%s) role_checked=%s proacl_is_null=%s proacl=%s',
                 e.schema, e.name, e.identity_argument_types, role_to_deny.rolename,
                 (p.proacl is null)::text,
                 coalesce(p.proacl::text, '<default: PUBLIC EXECUTE, not revoked>')) as line
    from expected_function e
    join pg_proc p
      on p.proname = e.name
     and oidvectortypes(p.proargtypes) = e.identity_argument_types
    join pg_namespace n on n.oid = p.pronamespace and n.nspname = e.schema
    cross join (values ('authenticated'::text), ('anon'::text)) role_to_deny(rolename)
   where not exists (
     select 1
     from expected_function_execute_acl g
     where g.function_schema = e.schema
       and g.function_name = e.name
       and g.identity_argument_types = e.identity_argument_types
   )
     and has_function_privilege(role_to_deny.rolename, p.oid, 'EXECUTE')
   limit 20
) d;
select is(
  (
    select
      (select count(*)
         from pg_proc p
         join pg_namespace n on n.oid = p.pronamespace
         cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
         join pg_authid r on r.oid = a.grantee
        where n.nspname = 'public' and p.prokind = 'f'
          and r.rolname in ('authenticated', 'service_role')
          and a.is_grantable)
      +
      (select count(*)
         from expected_function e
         join pg_proc p
           on p.proname = e.name
          and oidvectortypes(p.proargtypes) = e.identity_argument_types
         join pg_namespace n on n.oid = p.pronamespace and n.nspname = e.schema
         cross join (values ('authenticated'::text), ('anon'::text)) role_to_deny(rolename)
        where not exists (
          select 1
          from expected_function_execute_acl g
          where g.function_schema = e.schema
            and g.function_name = e.name
            and g.identity_argument_types = e.identity_argument_types
        )
          and has_function_privilege(role_to_deny.rolename, p.oid, 'EXECUTE'))
  )::bigint,
  0::bigint,
  '55 function_execute_acl NO_WEAKER: no WITH GRANT OPTION on 30 canonical grants and all 43 zero-grant function identities deny authenticated/anon EXECUTE'
);

