  ) missing),
  0::bigint,
  '57 storage_bucket NO_MISSING: every canonical (id,name,public,file_size_limit,allowed_mime_types) row must be present and matching in the live catalog'
);

select diag(d.line) from (
  select format('UNEXPECTED id=%s name=%s', x.id, x.name) as line
    from (
      select id, name, public, file_size_limit, allowed_mime_types from storage.buckets
      except
      select id, name, is_public, file_size_limit, allowed_mime_types from expected_storage_bucket
    ) x
   limit 20
) d;
select is(
  (select count(*)::bigint from (
    select id, name, public, file_size_limit, allowed_mime_types from storage.buckets
    except
    select id, name, is_public, file_size_limit, allowed_mime_types from expected_storage_bucket
  ) unexpected),
  0::bigint,
  '58 storage_bucket NO_UNEXPECTED: no live storage bucket may present an identity or field value absent from the canonical storage_bucket set'
);

select is(
  (select count(*)::bigint from (
    select id from storage.buckets group by id having count(*) > 1
  ) dup),
  0::bigint,
  '59 storage_bucket NO_DUPLICATE: bucket id must be unique in the live catalog'
);

select is(
  (select count(*)::bigint
     from expected_storage_bucket e
     join storage.buckets b on b.id = e.id
    where b.public is distinct from e.is_public
       or b.file_size_limit > e.file_size_limit),
  0::bigint,
  '60 storage_bucket NO_WEAKER: per-bucket public flag must match canonical exactly (dealer-branding public=true, the other 4 public=false) and no file_size_limit may increase beyond canonical'
);
-- r12c_ft_live.sql
-- Builds actual_function and actual_trigger shapes straight from pg_catalog,
-- then runs pgTAP assertions 61-71 (plan categories: function, trigger)
-- against the temp tables created by /private/tmp/r12c_ft_expected.sql
-- (expected_function, expected_trigger must already exist in this session).
--
-- BLOCKER (see R12C_FT_BLOCKER.md): normalized_definition is excluded from
-- the function NO_MISSING/NO_UNEXPECTED tuple (assertions 62/63) only. The
-- accepted R12B_F_FUNCTION.*.jsonl definition_normalized field is a
-- header-only (non-body) signature; pg_get_functiondef always returns the
-- full body-inclusive definition and additionally canonicalizes SET clause
-- syntax (`=` -> `TO`). Neither asymmetry can be closed without either a
-- deterministic false failure or a content-rewriting substitution that is
-- not provably safe from the artifacts available in this phase, so the
-- field is fail-closed excluded from that one comparison rather than
-- fabricating equality. All other 11 function fields remain exact, and the
-- trigger normalized_definition is also excluded from 68/69 because the
-- accepted source ledger intentionally preserves mixed qualification and
-- case (for example public-qualified and unqualified relation/function
-- names), while pg_get_triggerdef emits a canonical qualification/case.
-- The other 14 trigger semantic fields remain exact.

-- ============================================================
-- actual_function
-- ============================================================
create temp table actual_function as
select
  n.nspname::text as schema,
  p.proname::text as name,
  oidvectortypes(p.proargtypes) as identity_argument_types,
  case
    when rtn.nspname = 'pg_catalog' then pg_catalog.format_type(p.prorettype, null)
    else format('%I.%I', rtn.nspname, rt.typname)
  end as result_type,
  l.lanname::text as language,
  p.prosecdef as security_definer,
  p.provolatile::text as provolatile,
  p.proparallel::text as proparallel,
  p.proleakproof as leakproof,
  p.proisstrict as strict,
  p.proconfig as proconfig_in_order,
  pg_get_functiondef(p.oid) as normalized_definition
from pg_proc p
join pg_namespace n on n.oid = p.pronamespace
join pg_language l on l.oid = p.prolang
join pg_type rt on rt.oid = p.prorettype
join pg_namespace rtn on rtn.oid = rt.typnamespace
where n.nspname = 'public'
  and p.prokind = 'f';

-- ============================================================
-- actual_trigger
-- ============================================================
create temp table actual_trigger as
select
  n.nspname::text as schema,
  c.relname::text as relation,
  t.tgname::text as trigger_name,
  case when (t.tgtype::int & 2) = 2 then 'BEFORE'
       when (t.tgtype::int & 64) = 64 then 'INSTEAD OF'
       else 'AFTER'
  end as timing,
  case when (t.tgtype::int & 1) = 1 then 'ROW' else 'STATEMENT' end as orientation,
  (
    select array_agg(ev order by ord)
    from (
      select 1 as ord, 'INSERT' as ev where (t.tgtype::int & 4) = 4
      union all
      select 2, 'UPDATE' where (t.tgtype::int & 16) = 16
      union all
      select 3, 'DELETE' where (t.tgtype::int & 8) = 8
      union all
      select 4, 'TRUNCATE' where (t.tgtype::int & 32) = 32
    ) events
  ) as events,
  pg_get_expr(t.tgqual, t.tgrelid, true) as when_expression,
  nullif(
    trim(
      coalesce('OLD TABLE AS ' || nullif(t.tgoldtable::text, ''), '') ||
      case when t.tgoldtable is not null and t.tgnewtable is not null then ' ' else '' end ||
      coalesce('NEW TABLE AS ' || nullif(t.tgnewtable::text, ''), '')
    ),
    ''
  ) as referencing_clause,
  t.tgconstraint <> 0 as is_constraint_trigger,
  t.tgdeferrable as deferrable_flag,
  t.tginitdeferred as initially_deferred,
  fp.proname::text as target_function_name,
  pg_get_function_identity_arguments(fp.oid) as target_function_identity_argument_types,
  t.tgenabled::text as tgenabled,
  pg_get_triggerdef(t.oid, true) as normalized_definition
from pg_trigger t
join pg_class c on c.oid = t.tgrelid
join pg_namespace n on n.oid = c.relnamespace
join pg_proc fp on fp.oid = t.tgfoid
where n.nspname = 'public'
  and not t.tgisinternal;

-- ============================================================
-- Assertions 61-66: actual_function vs expected_function
-- ============================================================

-- 61: EXACT_COUNT
select is(
  (select count(*)::int from actual_function),
  70,
  '61: actual_function row count is 70 (64 pre-existing + 6 added by GDA-2A-OCR-POSTAL-MASTER-R2-A1)'
);

-- 62: NO_MISSING (full row, normalized_definition EXCLUDED -- see
-- R12C_FT_BLOCKER.md: header-only canonical text vs body-inclusive
-- pg_get_functiondef, plus SET-clause = vs TO canonicalization, cannot be
-- safely compared without fabricating equality or a false failure)
select diag(d.line) from (
  select format('MISSING schema=%s name=%s args=%s result=%s lang=%s secdef=%s provolatile=%s proparallel=%s leakproof=%s strict=%s proconfig=%s',
                 x.schema, x.name, x.identity_argument_types, x.result_type, x.language,
                 x.security_definer, x.provolatile, x.proparallel, x.leakproof, x.strict, x.proconfig_in_order) as line
    from (
      select schema, name, identity_argument_types, result_type, language,
             security_definer, provolatile, proparallel, leakproof, strict,
             proconfig_in_order
      from expected_function
      except
      select schema, name, identity_argument_types, result_type, language,
             security_definer, provolatile, proparallel, leakproof, strict,
             proconfig_in_order
      from actual_function
    ) x
   limit 20
) d;
select is_empty(
  $$
    select schema, name, identity_argument_types, result_type, language,
           security_definer, provolatile, proparallel, leakproof, strict,
           proconfig_in_order
    from expected_function
    except
    select schema, name, identity_argument_types, result_type, language,
           security_definer, provolatile, proparallel, leakproof, strict,
           proconfig_in_order
    from actual_function
  $$,
  '62: no function rows missing from actual vs expected (normalized_definition excluded, see R12C_FT_BLOCKER.md)'
);

-- 63: NO_UNEXPECTED (mirror of 62, normalized_definition EXCLUDED -- see
-- R12C_FT_BLOCKER.md)
select diag(d.line) from (
  select format('UNEXPECTED schema=%s name=%s args=%s result=%s lang=%s secdef=%s provolatile=%s proparallel=%s leakproof=%s strict=%s proconfig=%s',
                 x.schema, x.name, x.identity_argument_types, x.result_type, x.language,
                 x.security_definer, x.provolatile, x.proparallel, x.leakproof, x.strict, x.proconfig_in_order) as line
    from (
      select schema, name, identity_argument_types, result_type, language,
             security_definer, provolatile, proparallel, leakproof, strict,
             proconfig_in_order
      from actual_function
      except
      select schema, name, identity_argument_types, result_type, language,
             security_definer, provolatile, proparallel, leakproof, strict,
             proconfig_in_order
      from expected_function
    ) x
   limit 20
) d;
select is_empty(
  $$
    select schema, name, identity_argument_types, result_type, language,
           security_definer, provolatile, proparallel, leakproof, strict,
           proconfig_in_order
    from actual_function
    except
    select schema, name, identity_argument_types, result_type, language,
           security_definer, provolatile, proparallel, leakproof, strict,
           proconfig_in_order
    from expected_function
  $$,
  '63: no unexpected function rows in actual vs expected (normalized_definition excluded, see R12C_FT_BLOCKER.md)'
);

-- 64: NO_DUPLICATE
select is_empty(
  $$
    select schema, name, identity_argument_types
    from actual_function
    group by schema, name, identity_argument_types
    having count(*) > 1
  $$,
  '64: no duplicate actual_function overload identities'
);

-- 65: NO_WEAKER (SECURITY DEFINER functions must retain their canonical
-- proconfig_in_order; a SECURITY DEFINER function losing its search_path
-- pin is a security regression, not benign drift. Additional guard on top
-- of 62/63, not a substitute for them.)
select is_empty(
  $$
    select e.schema, e.name, e.identity_argument_types
    from expected_function e
    join actual_function a
      on a.schema = e.schema
     and a.name = e.name
     and a.identity_argument_types = e.identity_argument_types
    where e.security_definer = true
      and (a.proconfig_in_order is distinct from e.proconfig_in_order)
  $$,
  '65: no SECURITY DEFINER function weakened (proconfig_in_order/search_path pin dropped or changed)'
);

-- 66: OWNER_CONTRACT_LABELED (source-contract, see
-- 104_least_privilege_grants.sql lines 357-366; this assertion is only
-- runtime-verified if this SQL is actually executed against a live
-- database -- otherwise it documents the expected ownership contract)
select is(
  (
    select count(*)::int
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    join pg_authid a on a.oid = p.proowner
    join expected_function e
      on e.schema = n.nspname::text
     and e.name = p.proname::text
     and e.identity_argument_types = oidvectortypes(p.proargtypes)
    where n.nspname = 'public'
      and p.prokind = 'f'
      and exists (
        select 1
        from expected_function e
        where e.schema = n.nspname
          and e.name = p.proname
          and e.identity_argument_types = oidvectortypes(p.proargtypes)
      )
      and a.rolname <> 'postgres'
  ),
  0,
  '66: OWNER_CONTRACT_LABELED all public functions owned by postgres (source-contract, see 104_least_privilege_grants.sql lines 357-366)'
);

-- ============================================================
-- Assertions 67-71: actual_trigger vs expected_trigger
-- ============================================================

-- 67: EXACT_COUNT
select is(
  (select count(*)::int from actual_trigger),
  59,
  '67: actual_trigger row count is 59'
