-- R12C final static fragment: assertions 72-76 only.
-- Source-derived candidate; not executed in R12C.

-- 72 extension capability NO_WEAKER. The source analysis resolved zero
-- required optional extensions. Guard the exact families declared by R12B
-- against the final 64 public function bodies without asserting platform rows.
select is(
  (
    select count(*)::int
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
      and lower(p.prosrc) ~
        '(crypt\s*\(|gen_salt\s*\(|digest\s*\(|hmac\s*\(|pgp_sym_|pgp_pub_|gen_random_bytes\s*\(|uuid_generate_|similarity\s*\(|word_similarity\s*\(|show_trgm\s*\(|\mcitext\M|\mst_[a-z0-9_]+\s*\(|\mgeometry\M|\mgeography\M|\mvector\s*\(|<->|<#>|<=>|\mhstore\M|\mltree\M|crosstab\s*\(|levenshtein\s*\(|soundex\s*\(|metaphone\s*\(|dmetaphone\s*\(|difference\s*\(|cube\s*\(|earth_distance\s*\(|ll_to_earth\s*\(|http_get\s*\(|http_post\s*\(|net\.http_get\s*\(|net\.http_post\s*\(|cron\.|pgsodium\.|vault\.|unaccent\s*\()'
  ),
  0,
  '72 extension_capability NO_WEAKER: no final public function body references any of the 18 source-classified optional extension families'
);

-- 73 extension capability EXACT_COUNT. Empty application-required extension
-- name set; platform-managed inventory is intentionally not asserted.
select is(
  (
    select count(*)::int
    from pg_extension
    where extname = any(ARRAY[]::text[])
  ),
