-- 75: reworked from a results_eq(...) call that compared two independently
-- prepared cursors (a name-cast-to-text catalog column vs a bare text
-- literal) and aborted the transaction with an unresolvable-collation
-- error before ever producing a pass/fail. Rebuilt using this file's own
-- established is_empty()+EXCEPT symmetric-difference idiom (single query,
-- single execution context, identical in shape to every other missing/
-- unexpected pair in this suite) so ordinary collation resolution applies
-- and the comparison can complete. Does not change plan(76): one diag()
-- (non-counted) plus one is_empty() (one assertion slot, same as before).
select diag(d.line) from (
  select format('SCHEMA_DIFF %s', x.schema_name) as line
    from (
      (
        select schema_name::text
        from information_schema.schemata
        where schema_name not in (
          -- Supabase-managed platform schemas
