          'auth', 'storage', 'extensions', 'graphql', 'graphql_public',
          'net', 'pgbouncer', 'realtime', 'vault', 'pgsodium', 'cron',
          'supabase_functions', 'supabase_migrations', '_realtime',
          -- this test file's own shadow schemas (created above, design traceability only)
          'r12c_catalog_pgtap', 'r12c_expected_public', 'r12c_expected_storage'
        )
          and schema_name !~ '^pg_(temp|toast)_'
      )
    ) x
   limit 20
) d;
select is_empty(
  $$
    (
      select schema_name::text
      from information_schema.schemata
      where schema_name not in (
        'pg_catalog', 'pg_temp', 'pg_toast', 'information_schema',
        'auth', 'storage', 'extensions', 'graphql', 'graphql_public',
        'net', 'pgbouncer', 'realtime', 'vault', 'pgsodium', 'cron',
